80	import { useCleanupTemporaryBaskets } from '@salesforce/retail-react-app/app/hooks/use-cleanup-temporary-baskets';
81	
82	/*
83	 * These are a deliberate temporary gap, NOT evidence that no type exists — do not read them
84	 * that way. `@salesforce/retail-react-app` ships no TypeScript types (see
85	 * overrides/app/types/vendor.d.ts), but the shapes underneath are `commerce-sdk-isomorphic`'s
86	 * and it does export them: `ShopperProductsTypes.Product` / `.Variant` / `.Category`, and
87	 * `.Image` for `image` below. AGENTS.md's Type Definitions rule says to import those directly.
88	 *
89	 * Substituting them is a follow-up rather than part of this PR only because it also removes
90	 * three `no-explicit-any` warnings, moving a lint count this branch holds as an invariant
91	 * across every commit.
92	 */
93	type SfccProduct = any;
94	type SfccVariant = any;
95	type SfccCategory = any;
96	type SfccPriceData = any;
97	
98	/** One selectable value of a variation attribute, as the base hooks shape it. */
99	type SfccVariationValue = { href?: string; name: string; image?: SfccProduct; value?: string; orderable?: boolean };
100	
101	/** A variation attribute (colour, size, ...) with its selectable values. */
102	type SfccVariationAttribute = {
103	  id: string;
104	  name?: string;
105	  selectedValue?: SfccVariationValue;
106	  values: SfccVariationValue[];
107	};
108	
109	/** The per-child orderability record ProductView writes back to its parent. */
110	export type ChildProductOrderability = {
111	  showInventoryMessage?: boolean;
112	  unfulfillable?: boolean;
113	  isOutOfStock?: boolean;
114	  stockLevel?: number;
115	  productName?: string;
116	};
117	
118	export type ProductViewHeaderProps = {
119	  name?: string;
120	  currency?: string;
121	  priceData?: SfccPriceData;
122	  category?: SfccCategory[];
123	  product?: SfccProduct;
124	  isProductPartOfBundle?: boolean;
125	};
126	
127	/*
128	 * Mirrors the base file's `ProductView.propTypes` one-for-one, with the defaults declared in
129	 * the destructuring below reflected as optional. `validateOrderability`'s signature is taken
130	 * from the default implementation the base file supplies.
131	 */
132	type ProductViewProps = {
133	  product?: SfccProduct;
134	  category?: SfccCategory[];
135	  showFullLink?: boolean;
136	  imageSize?: 'sm' | 'md';
137	  isWishlistLoading?: boolean;
138	  addToCart?: ((productSelectionValues: SfccProduct[]) => unknown) | null;
139	  updateCart?: ((variant: SfccVariant, quantity: number) => unknown) | null;
140	  addToWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
141	  updateWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
142	  isProductLoading?: boolean;
143	  isProductPartOfSet?: boolean;
144	  isProductPartOfBundle?: boolean;
145	  childOfBundleQuantity?: number;
146	  childProductOrderability?: Record<string, ChildProductOrderability>;
147	  setChildProductOrderability?: React.Dispatch<React.SetStateAction<Record<string, ChildProductOrderability>>>;
148	  isBasketLoading?: boolean;
149	  onVariantSelected?: (product: SfccProduct, variant: SfccVariant, quantity: number) => void;
150	  validateOrderability?: (
151	    variant: SfccVariant,
152	    product: SfccProduct,
153	    quantity: number,
154	    stockLevel: number,
155	  ) => boolean | undefined;
156	  showImageGallery?: boolean;
157	  setSelectedBundleQuantity?: (quantity: number) => void;
158	  selectedBundleParentQuantity?: number;
159	  pickupInStore?: boolean;
160	  setPickupInStore?: (checked: boolean) => void;
161	  onOpenStoreLocator?: () => void;
162	  showDeliveryOptions?: boolean;
163	  customButtons?: React.ReactElement[];
164	  promotionId?: string;
165	  maxOrderQuantity?: number | null;
166	  imageGalleryFooter?: React.ReactNode;
167	  alignItems?: string;
168	  controlledVariationValues?: Record<string, string> | null;
169	  onVariationChange?: ((attributeId: string, value: string) => void) | null;
170	  /**
171	   * The one Zimmermann addition to this component's prop surface. Replaces the header block
172	   * (breadcrumb, title, price, promo callout) with caller-supplied content, receiving exactly
173	   * the values the private `ProductViewHeader` is given so a caller can reuse or ignore any of
174	   * them. Defaults to rendering that same private header, so every existing caller — cart,
175	   * wishlist, bonus-product — is byte-identical unless it opts in.
176	   *
177	   * ProductView renders the header twice (mobile and desktop breakpoints), so this is called
178	   * twice with the same arguments. Keep it pure.
179	   */
180	  renderHeader?: (props: ProductViewHeaderProps) => React.ReactNode;
181	  /**
182	   * A caller-supplied override for rendering a single variation attribute (e.g. colour,
183	   * size), receiving the full attribute object so a caller can reuse or ignore any of its
184	   * fields. Falls through to `renderDefaultVariationAttribute` — the extracted base rendering
185	   * for that attribute — via `??` at the call site. ProductView calls this once per entry in
186	   * `variationAttributes`; keep it pure.
187	   *
188	   * That `??` only treats `undefined` as absent: returning `undefined` falls through to the
189	   * base rendering for that attribute, but returning `null` ALSO falls through and is NOT a
190	   * way to render nothing for that attribute — render an empty fragment instead if that's
191	   * genuinely the intent.
192	   */
193	  renderVariationAttribute?: (attr: SfccVariationAttribute) => React.ReactNode;
194	};
195	
196	/*
197	 * The base file rebinds a function ref's `this` so the parent can reach `validateOrderability`
198	 * (see the `typeof ref === 'function'` branch below, and the set/bundle child refs in
199	 * pages/product-detail).
200	 */
201	type ProductViewRef = React.ForwardedRef<HTMLDivElement>;
202	
203	/**
204	 * The scope ProductView rebinds onto a callback `ref`, so a parent rendering set/bundle
205	 * children can reach this instance's validation. See the `typeof ref === 'function'` branch
206	 * below. A consumer names it as the `this` parameter of its ref callback —
207	 * `function (this: ProductViewRefScope, ref) { ... }` — which TypeScript accepts as a `ref`
208	 * as written; no assertion is required at the prop site.
209	 */
210	export type ProductViewRefScope = {
211	  validateOrderability: (opts: { scrollErrorIntoView: boolean }) => void;
212	};
213	
214	const ProductViewHeader = ({
215	  name,
216	  currency,
217	  priceData,
218	  category,
219	  product,
220	  isProductPartOfBundle,
221	}: ProductViewHeaderProps) => {
222	  return (
223	    <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
224	      {category && (
225	        <Skeleton isLoaded={category} minWidth={64}>
226	          <Breadcrumb categories={category} />
227	        </Skeleton>
228	      )}
229	
230	      {/* Title */}
231	      <Skeleton isLoaded={name}>
232	        <Heading fontSize="2xl">{`${name}`}</Heading>
233	      </Skeleton>
234	
235	      {!isProductPartOfBundle && (
236	        <>
237	          <Skeleton isLoaded={priceData?.currentPrice}>
238	            {priceData?.currentPrice && <DisplayPrice priceData={priceData} currency={currency} />}
239	          </Skeleton>
240	
241	          <Skeleton isLoaded={product}>{product?.productPromotions && <PromoCallout product={product} />}</Skeleton>
242	        </>
243	      )}
244	    </VStack>
245	  );
246	};
247	
248	const ButtonWithRegistration = withRegistration(Button);
249	
250	/**
251	 * Render a product detail view that includes name, image gallery, price,
252	 * variant selections, action buttons
253	 */
254	
255	const ProductView = forwardRef(
256	  (
257	    {
258	      product,
259	      category,
260	      showFullLink = false,
261	      imageSize = 'md',
262	      isWishlistLoading = false,
263	      addToCart,
264	      updateCart,
265	      addToWishlist,
266	      updateWishlist,
267	      isProductLoading,
268	      isProductPartOfSet = false,
269	      isProductPartOfBundle = false,
270	      childOfBundleQuantity = 0,
271	      childProductOrderability,
272	      setChildProductOrderability,
273	      isBasketLoading = false,
274	      onVariantSelected = () => {},
275	      validateOrderability = (variant, product, quantity, stockLevel) => {
276	        if (isProductLoading) return false;
277	
278	        // If product has variations, a variant must be selected
279	        if (product?.variationAttributes?.length > 0 && !variant) {
280	          return false;
281	        }
282	
283	        // Check if product (either variant or standard) is orderable and if quantity is valid
284	        return (variant?.orderable || product?.inventory?.orderable) && quantity > 0 && quantity <= stockLevel;
285	      },
286	      showImageGallery = true,
287	      setSelectedBundleQuantity = () => {},
288	      selectedBundleParentQuantity = 1,
289	      pickupInStore = false,
290	      setPickupInStore = () => {},
291	      onOpenStoreLocator = () => {},
292	      showDeliveryOptions = true,
293	      customButtons = [],
294	      maxOrderQuantity = null,
295	      imageGalleryFooter = null,
296	      controlledVariationValues = null,
297	      onVariationChange = null,
298	      renderHeader = (headerProps: ProductViewHeaderProps) => <ProductViewHeader {...headerProps} />,
299	      renderVariationAttribute,
300	    }: ProductViewProps,
301	    ref: ProductViewRef,
302	  ) => {
303	    const { currency: activeCurrency } = useCurrency();
304	    const showToast = useToast();
305	    const intl = useIntl();
306	    const location = useLocation();
307	    const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
308	    const {
309	      isOpen: isAddToCartModalOpen,
310	      onOpen: onAddToCartModalOpen,
311	      onClose: onAddToCartModalClose,
312	    } = useAddToCartModalContext();
313	
314	    const { mutateAsync: createBasket } = useShopperBasketsMutation('createBasket');
315	    const { mutateAsync: addItemToBasket } = useShopperBasketsMutation('addItemToBasket');
316	
317	    const theme = useTheme();
318	    const { confirmingBasket } = useSFPayments();
319	    const [showOptionsMessage, toggleShowOptionsMessage] = useState(false);
320	    const {
321	      showLoading,
322	      showInventoryMessage,
323	      inventoryMessage,
324	      quantity,
325	      minOrderQuantity,
326	      setQuantity,
327	      variant,
328	      variationParams,
329	      variationAttributes,
330	      stockLevel,
331	      stepQuantity,
332	      isOutOfStock,
333	      unfulfillable,
334	      isSelectedStoreOutOfStock,
335	      selectedStore,
336	    } = useDerivedProduct(
337	      product,
338	      isProductPartOfSet,
339	      isProductPartOfBundle,
340	      pickupInStore,
341	      controlledVariationValues,
342	      onVariationChange,
343	    );
344	    const priceData = useMemo(() => {
345	      return getPriceData(product, { quantity });
346	    }, [product, quantity]);
347	    const canAddToWishlist = !isProductLoading;
348	    const isProductASet = product?.type?.set;
349	    const isProductABundle = product?.type?.bundle;
350	    const errorContainerRef = useRef<HTMLDivElement | null>(null);
351	    const [pickupEnabled, setPickupEnabled] = useState(false);
352	    const storeName = selectedStore?.name;
353	    const inventoryId = selectedStore?.inventoryId;
354	    const { pdp: showExpressOnPDP } = useExpressCheckoutEnabled();
355	
356	    const { disableButton, customInventoryMessage } = useMemo(() => {
357	      let shouldDisableButton = showInventoryMessage;
358	      let currentInventoryMsg = '';
359	      if (!shouldDisableButton && (isProductASet || isProductABundle) && childProductOrderability) {
360	        // if any of the children are not orderable, it will disable the add to cart button
361	        const unavailableChildProductKey = Object.keys(childProductOrderability).find((key) => {
362	          return childProductOrderability[key].showInventoryMessage;
363	        });
364	        shouldDisableButton = !!unavailableChildProductKey;
365	        if (unavailableChildProductKey) {
366	          const unavailableChildProduct = childProductOrderability[unavailableChildProductKey];
367	          if (unavailableChildProduct.unfulfillable) {
368	            currentInventoryMsg = intl.formatMessage(
369	              {
370	                defaultMessage: 'Only {stockLevel} left for {productName}!',
371	                id: 'use_product.message.inventory_remaining_for_product',
372	              },
373	              {
374	                stockLevel: unavailableChildProduct.stockLevel,
375	                productName: unavailableChildProduct.productName,
376	              },
377	            );
378	          }
379	          if (unavailableChildProduct.isOutOfStock) {
380	            currentInventoryMsg = intl.formatMessage(
381	              {
382	                defaultMessage: 'Out of stock for {productName}',
383	                id: 'use_product.message.out_of_stock_for_product',
384	              },
385	              { productName: unavailableChildProduct.productName },
386	            );
387	          }
388	        }
389	      }
390	      return { disableButton: shouldDisableButton, customInventoryMessage: currentInventoryMsg };
391	    }, [showInventoryMessage, childProductOrderability]);
392	
393	    const validateAndShowError = (opts: { scrollErrorIntoView?: boolean } = {}) => {
394	      const { scrollErrorIntoView = true } = opts;
395	      // Validate that all attributes are selected before proceeding.
396	      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
397	      const showError = !isProductASet && !isProductABundle && !hasValidSelection;
398	      const scrollToError = showError && scrollErrorIntoView;
399	
400	      toggleShowOptionsMessage(showError);
401	
402	      if (scrollToError) {
403	        // Deviation from the base file: `?.`. The base dereferences `current` unguarded here
404	        // while guarding it in `prepareBasket` below; the two only differ if the error
405	        // container has not mounted, where the base throws.
406	        errorContainerRef.current?.scrollIntoView({
407	          behavior: 'smooth',
408	          block: 'center',
409	        });
410	      }
411	
412	      return hasValidSelection;
413	    };
414	    const cleanupTemporaryBaskets = useCleanupTemporaryBaskets();
415	
416	    // prepareBasket is used to prepare the basket for express payments
417	    // useCallback recreates prepareBasket primarily when product or quantity change, along with variant, stockLevel, and product type flags (isProductASet, isProductABundle)
418	    const prepareBasket = useCallback(async () => {
419	      // Validate that all attributes are selected before proceeding
420	      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
421	      let errorMessage = '';
422	
423	      if (!hasValidSelection && !isProductASet && !isProductABundle) {
424	        toggleShowOptionsMessage(true);
425	        if (errorContainerRef.current) {
426	          errorContainerRef.current.scrollIntoView({
427	            behavior: 'smooth',
428	            block: 'center',
429	          });
430	        }
431	        errorMessage = intl.formatMessage({
432	          defaultMessage: 'Please select all product options before proceeding with Express Payments',
433	          id: 'product_view.prepareBasket',
434	        });
435	
436	        const error: Error & { isValidationError?: boolean } = new Error(errorMessage);
437	        error.isValidationError = true;
438	        throw error;
439	      }
440	
441	      // Clean up temporary baskets before creating a new one
442	      await cleanupTemporaryBaskets();
443	
444	      // Create a new temporary basket
445	      const newBasket = await createBasket({
446	        parameters: {
447	          temporary: true,
448	        },
449	        body: {},
450	      });
451	
452	      const selectedProduct = variant || product;
453	      // Use variant's productId if variant is selected, otherwise use product's id
454	      const productIdToUse = selectedProduct?.productId || selectedProduct?.id;
455	
456	      if (!productIdToUse) {
457	        errorMessage = intl.formatMessage({
458	          defaultMessage: 'Unable to determine product ID for basket',
459	          id: 'product_view.prepareBasket',
460	        });
461	        throw new Error(errorMessage);
462	      }
463	      // Add the product to the temporary basket
464	      const basketWithItem = await addItemToBasket({
465	        // SDK param widening — `newBasket` is the basket just created above.
466	        parameters: { basketId: newBasket.basketId as string },
467	        body: [
468	          {
469	            productId: productIdToUse,
470	            quantity: quantity,
471	          },
472	        ],
473	      });
474	
475	      return basketWithItem;
476	    }, [variant, product, quantity, stockLevel, isProductASet, isProductABundle]);
477	
478	    const renderActionButtons = () => {
479	      const buttons = [];
480	      const buttonText = {
481	        update: intl.formatMessage({
482	          defaultMessage: 'Update',
483	          id: 'product_view.button.update',
484	        }),
485	        addToCart: intl.formatMessage({
486	          defaultMessage: 'Add to Cart',
487	          id: 'product_view.button.add_to_cart',
488	        }),
489	        addSetToCart: intl.formatMessage({
490	          defaultMessage: 'Add Set to Cart',
491	          id: 'product_view.button.add_set_to_cart',
492	        }),
493	        addBundleToCart: intl.formatMessage({
494	          defaultMessage: 'Add Bundle to Cart',
495	          id: 'product_view.button.add_bundle_to_cart',
496	        }),
497	        addToWishlist: intl.formatMessage({
498	          defaultMessage: 'Add to Wishlist',
499	          id: 'product_view.button.add_to_wishlist',
500	        }),
501	        addSetToWishlist: intl.formatMessage({
502	          defaultMessage: 'Add Set to Wishlist',
503	          id: 'product_view.button.add_set_to_wishlist',
504	        }),
505	        addBundleToWishlist: intl.formatMessage({
506	          defaultMessage: 'Add Bundle to Wishlist',
507	          id: 'product_view.button.add_bundle_to_wishlist',
508	        }),
509	      };
510	
511	      const showError = () => {
512	        showToast({
513	          title: intl.formatMessage(API_ERROR_MESSAGE),
514	          status: 'error',
515	        });
516	      };
517	
518	      const handleCartItem = async () => {
519	        const hasValidSelection = validateAndShowError();
520	
521	        if (!hasValidSelection) {
522	          return null;
523	        }
524	
525	        if (!addToCart && !updateCart) return null;
526	        if (updateCart) {
527	          await updateCart(variant || product, quantity);
528	          return;
529	        }
530	        try {
531	          // Guarded above: `!addToCart && !updateCart` returns early, and the `updateCart`
532	          // branch returns, so `addToCart` is defined here. TypeScript cannot narrow across
533	          // those two statements.
534	          const itemsAdded = await addToCart!([{ product, variant, quantity }]);
535	          // Open modal only when `addToCart` returns some data
536	          // It's possible that the item has been added to cart, but we don't want to open the modal.
537	          // See wishlist_primary_action for example.
538	          if (itemsAdded) {
539	            onAddToCartModalOpen({
540	              product,
541	              itemsAdded,
542	              selectedQuantity: quantity,
543	            });
544	          }
545	        } catch (e) {
546	          showError();
547	        }
548	      };
549	
550	      const handleWishlistItem = async () => {
551	        if (!updateWishlist && !addToWishlist) return null;
552	        if (updateWishlist) {
553	          updateWishlist(product, variant, quantity);
554	          return;
555	        }
556	        // Guarded above, exactly as `addToCart` is in handleCartItem.
557	        addToWishlist!(product, variant, quantity);
558	      };
559	
560	      // child product of bundles do not have add to cart button
561	      if ((addToCart || updateCart) && !isProductPartOfBundle) {
562	        buttons.push(
563	          <Button
564	            key="cart-button"
565	            onClick={handleCartItem}
566	            isDisabled={disableButton}
567	            isLoading={isBasketLoading}
568	            width="100%"
569	            variant="solid"
570	            marginBottom={4}
571	          >
572	            {updateCart
573	              ? buttonText.update
574	              : isProductASet
575	              ? buttonText.addSetToCart
576	              : isProductABundle
577	              ? buttonText.addBundleToCart
578	              : buttonText.addToCart}
579	          </Button>,
580	        );
581	      }
582	
583	      // child product of bundles do not have add to wishlist button
584	      if ((addToWishlist || updateWishlist) && !isProductPartOfBundle) {
585	        buttons.push(
586	          <ButtonWithRegistration
587	            key="wishlist-button"
588	            onClick={handleWishlistItem}
589	            disabled={isWishlistLoading || !canAddToWishlist}
590	            isLoading={isWishlistLoading}
591	            width="100%"
592	            variant="outline"
593	            marginBottom={4}
594	          >
595	            {updateWishlist
596	              ? buttonText.update
597	              : isProductASet
598	              ? buttonText.addSetToWishlist
599	              : isProductABundle
600	              ? buttonText.addBundleToWishlist
601	              : buttonText.addToWishlist}
602	          </ButtonWithRegistration>,
603	        );
604	      }
605	
606	      if (showExpressOnPDP && !isProductASet && !isProductPartOfBundle && activeCurrency && priceData.currentPrice) {
607	        buttons.push(
608	          <SFPaymentsExpressButtons
609	            key="express-buttons"
610	            usage={EXPRESS_BUY_NOW}
611	            paymentCurrency={activeCurrency}
612	            paymentCountryCode={null}
613	            initialAmount={priceData.currentPrice}
614	            prepareBasket={prepareBasket}
615	            expressButtonLayout="vertical"
616	            maximumButtonCount={1}
617	          />,
618	        );
619	      }
620	
621	      // Add custom buttons if provided
622	      if (customButtons && customButtons.length > 0) {
623	        customButtons.forEach((customButton, index) => {
624	          buttons.push(
625	            React.cloneElement(customButton, {
626	              key: `custom-button-${index}`,
627	              width: customButton.props.width || '100%',
628	              marginBottom: customButton.props.marginBottom || 4,
629	            }),
630	          );
631	        });
632	      }
633	
634	      return buttons;
635	    };
636	
637	    // Bind the reference with our `scope` that includes the internal validate function for this component.
638	    // Other values can be added to this scope as required.
639	    if (typeof ref === 'function') {
640	      ref = ref.bind({ validateOrderability: validateAndShowError });
641	    }
642	
643	    // Set the quantity of bundle child in a product bundle to ensure availability messages appear
644	    if (isProductPartOfBundle && quantity != selectedBundleParentQuantity * childOfBundleQuantity) {
645	      setQuantity(selectedBundleParentQuantity * childOfBundleQuantity);
646	    }
647	
648	    useEffect(() => {
649	      if (isAddToCartModalOpen) {
650	        onAddToCartModalClose();
651	      }
652	    }, [location.pathname]);
653	
654	    useEffect(() => {
655	      if (!isProductASet && !isProductABundle && validateOrderability(variant, product, quantity, stockLevel)) {
656	        toggleShowOptionsMessage(false);
657	      }
658	    }, [variationParams]);
659	
660	    useEffect(() => {
661	      if (variant) {
662	        onVariantSelected(product, variant, quantity);
663	      }
664	    }, [variant?.productId, quantity]);
665	
666	    useEffect(() => {
667	      if ((isProductPartOfBundle || isProductPartOfSet) && product && product.type?.item) {
668	        onVariantSelected(product, null, childOfBundleQuantity || quantity);
669	      }
670	    }, [product, childOfBundleQuantity, quantity, isProductPartOfBundle, isProductPartOfSet]);
671	
672	    useEffect(() => {
673	      if (isProductPartOfBundle || isProductPartOfSet) {
674	        const key = product.itemId ?? product.id;
675	        // when showInventoryMessage is true, it means child product is not orderable
676	        // Deviation from the base file: optional call. The prop has no default, and the base
677	        // calls it unguarded — only reachable for set/bundle children, whose parent always
678	        // supplies it.
679	        setChildProductOrderability?.((previousState) => ({
680	          ...previousState,
681	          [key]: {
682	            showInventoryMessage,
683	            isOutOfStock,
684	            unfulfillable,
685	            stockLevel,
686	            productName: product?.name,
687	          },
688	        }));
689	      }
690	    }, [showInventoryMessage, inventoryMessage]);
691	
692	    // Auto-switch off pickup in store when product becomes unavailable at selected store
693	    useEffect(() => {
694	      setPickupEnabled(!!selectedStore?.inventoryId);
695	      if (pickupInStore && isSelectedStoreOutOfStock) {
696	        setPickupInStore(false);
697	      }
698	    }, [selectedStore]);
699	
700	    const handleDeliveryOptionChange = (value: string) => {
701	      setPickupInStore(value === DELIVERY_OPTIONS.PICKUP);
702	    };
703	
704	    const renderDefaultVariationAttribute = (attr: SfccVariationAttribute) => {
705	      const { id, name, selectedValue, values } = attr;
706	      const swatches = values.map(({ href, name, image, value, orderable }: SfccVariationValue, index: number) => {
707	        // audit-allow: verbatim from base product-view (index.jsx:689); copy-first requires it unchanged
708	        const content = image ? (
709	          <Box
710	            height="100%"
711	            width="100%"
712	            minWidth="32px"
713	            backgroundRepeat="no-repeat"
714	            backgroundSize="cover"
715	            backgroundColor={name.toLowerCase()}
716	            backgroundImage={`url(${image.disBaseLink || image.link})`}
717	          />
718	        ) : (
719	          name
720	        );
721	        const hasSelection = Boolean(selectedValue?.value);
722	        const isSelected = selectedValue?.value === value;
723	        const isFirst = index === 0;
724	        // To mimic the behavior of a native radio input, only
725	        // one swatch should receive tab focus; the rest can be
726	        // selected using arrow keys when the swatch group has
727	        // focus. The focused element is the selected option or
728	        // the first in the group, if no option is selected.
729	        // This is a slight difference, for simplicity, from the
730	        // native element, where the first element is focused on
731	        // `Tab` and the _last_ element is focused on `Shift+Tab`
732	        const isFocusable = isSelected || (!hasSelection && isFirst);
733	        return (
734	          <Swatch
735	            key={value}
736	            href={href}
737	            disabled={!orderable}
738	            value={value}
739	            name={name}
740	            variant={id === 'color' ? 'circle' : 'square'}
741	            selected={isSelected}
742	            isFocusable={isFocusable}
743	          >
744	            {content}
745	          </Swatch>
746	        );
747	      });
748	      return (
749	        <SwatchGroup
750	          key={id}
751	          value={selectedValue?.value}
752	          displayName={selectedValue?.name || ''}
753	          label={intl.formatMessage(
754	            {
755	              defaultMessage: '{variantType}',
756	              id: 'product_view.label.variant_type',
757	            },
758	            { variantType: name },
759	          )}
760	          handleChange={onVariationChange ? (value: string) => onVariationChange(id, value) : undefined}
761	        >
762	          {swatches}
763	        </SwatchGroup>
764	      );
765	    };
766	
767	    return (
768	      <Flex direction={'column'} data-testid="product-view" ref={ref}>
769	        {/* Basic information etc. title, price, breadcrumb*/}
770	        <Box display={['block', 'block', 'block', 'none']}>
771	          {renderHeader({
772	            name: product?.name,
773	            product,
774	            priceData,
775	            currency: product?.currency || activeCurrency,
776	            category,
777	            isProductPartOfBundle,
778	          })}
779	        </Box>
780	        <Flex direction={['column', 'column', 'column', 'row']}>
781	          {showImageGallery && (
782	            <Box flex={1} mr={[0, 0, 0, 6, 6]}>
783	              {product ? (
784	                <>
785	                  <ImageGallery
786	                    size={imageSize}
787	                    imageGroups={product.imageGroups}
788	                    selectedVariationAttributes={variationParams}
789	                    lazy={isProductPartOfSet || isProductPartOfBundle}
790	                  />
791	                  <HideOnMobile>
792	                    {showFullLink && product && (
793	                      <Link to={`/product/${product.master.masterId}`} color="blue.600">
794	                        <FormattedMessage id="product_view.link.full_details" defaultMessage="See full details" />
795	                      </Link>
796	                    )}
797	                  </HideOnMobile>
798	                </>
799	              ) : (
800	                <ImageGallerySkeleton />
801	              )}
802	              {/* Custom footer content (e.g., Back to Selection button) */}
803	              {imageGalleryFooter && (
804	                <Box mt={6} mb={2}>
805	                  {imageGalleryFooter}
806	                </Box>
807	              )}
808	            </Box>
809	          )}
810	
811	          {/* Variations & Quantity Selector & CTA buttons */}
812	          {/* audit-allow: verbatim from base product-view (index.jsx:636-638); copy-first requires it unchanged */}
813	          <VStack
814	            align="stretch"
815	            spacing={8}
816	            flex={1}
817	            pb={[
818	              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
819	              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
820	              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
821	              4,
822	            ]}
823	          >
824	            <Box display={['none', 'none', 'none', 'block']}>
825	              {renderHeader({
826	                name: product?.name,
827	                product,
828	                priceData,
829	                currency: product?.currency || activeCurrency,
830	                category,
831	                isProductPartOfBundle,
832	              })}
833	            </Box>
834	            <VStack align="stretch" spacing={4}>
835	              {isProductPartOfBundle && (
836	                <Box>
837	                  <Text fontWeight="medium" fontSize="md" aria-label="price">
838	                    <label>
839	                      {intl.formatMessage({
840	                        defaultMessage: 'Quantity',
841	                        id: 'product_view.label.quantity',
842	                      })}
843	                      : {childOfBundleQuantity}
844	                    </label>
845	                  </Text>
846	                </Box>
847	              )}
848	              {/*
849	                                Customize the skeletons shown for attributes to suit your needs. At the point
850	                                that we show the skeleton we do not know how many variations are selectable. So choose
851	                                a a skeleton that will meet most of your needs.
852	                            */}
853	              {showLoading ? (
854	                <>
855	                  {/* First Attribute Skeleton */}
856	                  <Skeleton height={6} width={32} />
857	                  <Skeleton height={20} width={64} />
858	
859	                  {/* Second Attribute Skeleton */}
860	                  <Skeleton height={6} width={32} />
861	                  <Skeleton height={20} width={64} />
862	                </>
863	              ) : (
864	                variationAttributes.map((attr: SfccVariationAttribute) => (
865	                  <React.Fragment key={attr.id}>
866	                    {renderVariationAttribute?.(attr) ?? renderDefaultVariationAttribute(attr)}
867	                  </React.Fragment>
868	                ))
869	              )}
870	
871	              {/* audit-allow: verbatim from base product-view (index.jsx:754); copy-first requires it unchanged */}
872	              {!isProductASet && !isProductPartOfBundle && (
873	                <VStack align="stretch" maxWidth={'200px'}>
874	                  <Box fontWeight="bold">
875	                    <label htmlFor="quantity">
876	                      {intl.formatMessage({
877	                        defaultMessage: 'Quantity:',
878	                        id: 'product_view.label.quantity',
879	                      })}
880	                    </label>
881	                  </Box>
882	
883	                  <QuantityPicker
884	                    id="quantity"
885	                    step={stepQuantity}
886	                    value={quantity}
887	                    min={minOrderQuantity}
888	                    {...(maxOrderQuantity != null && { max: maxOrderQuantity })}
889	                    onChange={(stringValue: string, numberValue: number) => {
890	                      // Set the Quantity of product to value of input if value number
891	                      if (numberValue >= 0) {
892	                        setQuantity(numberValue);
893	                        if (isProductABundle) setSelectedBundleQuantity(numberValue);
894	                      } else if (stringValue === '') {
895	                        // We want to allow the use to clear the input to start a new input so here we set the quantity to '' so NAN is not displayed
896	                        // User will not be able to add '' qauntity to the cart due to the add to cart button enablement rules
897	                        setQuantity(stringValue);
898	                      }
899	                    }}
900	                    onBlur={(e: React.FocusEvent<HTMLInputElement>) => {
901	                      // Default to 1the `minOrderQuantity` if a user leaves the box with an invalid value
902	                      const value = e.target.value;
903	                      if (parseInt(value) < 0 || value === '') {
904	                        setQuantity(minOrderQuantity);
905	                        if (isProductABundle) setSelectedBundleQuantity(minOrderQuantity);
906	                      }
907	                    }}
908	                    onFocus={(e: React.FocusEvent<HTMLInputElement>) => {
909	                      // This is useful for mobile devices, this allows the user to pop open the keyboard and set the
910	                      // new quantity with one click. NOTE: This is something that can be refactored into the parent
911	                      // component, potentially as a prop called `selectInputOnFocus`.
912	                      e.target.select();
913	                    }}
914	                    productName={product?.name}
915	                  />
916	                </VStack>
917	              )}
918	              <Box ref={errorContainerRef}>
919	                {!showLoading && showOptionsMessage && (
920	                  <Fade in={true}>
921	                    <Text color="orange.600" fontWeight={600} marginBottom={8}>
922	                      {intl.formatMessage({
923	                        defaultMessage: 'Please select all your options above',
924	                      })}
925	                    </Text>
926	                  </Fade>
927	                )}
928	              </Box>
929	              <HideOnDesktop>
930	                {showFullLink && product && (
931	                  <Link to={`/product/${product.master.masterId}`} color="blue.600">
932	                    <FormattedMessage id="product_view.link.full_details" defaultMessage="See full details" />
933	                  </Link>
934	                )}
935	              </HideOnDesktop>
936	              {isProductASet && <p>{product?.shortDescription}</p>}
937	            </VStack>
938	
939	            <Box>
940	              {!showLoading && showInventoryMessage && !customInventoryMessage && (
941	                <Fade in={true}>
942	                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
943	                    {inventoryMessage}
944	                  </Text>
945	                </Fade>
946	              )}
947	              {!showLoading && customInventoryMessage && (
948	                <Fade in={true}>
949	                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
950	                    {customInventoryMessage}
951	                  </Text>
952	                </Fade>
953	              )}
954	              <Box>
955	                {showDeliveryOptions && (
956	                  <>
957	                    <Box mb={4}>
958	                      <Text fontWeight={600} mb={3}>
959	                        <FormattedMessage defaultMessage="Delivery:" id="product_view.label.delivery" />
960	                      </Text>
961	                      <RadioGroup
962	                        value={pickupInStore ? DELIVERY_OPTIONS.PICKUP : DELIVERY_OPTIONS.DELIVERY}
963	                        onChange={handleDeliveryOptionChange}
964	                        mb={1}
965	                      >
966	                        <Stack direction="column" spacing={2}>
967	                          <Radio value={DELIVERY_OPTIONS.DELIVERY} isDisabled={disableButton}>
968	                            <FormattedMessage
969	                              defaultMessage="Ship to Address"
970	                              id="product_view.label.ship_to_address"
971	                            />
972	                          </Radio>
973	                          {storeLocatorEnabled && (
974	                            <Radio
975	                              value={DELIVERY_OPTIONS.PICKUP}
976	                              isDisabled={!pickupEnabled || (storeName && inventoryId && isSelectedStoreOutOfStock)}
977	                            >
978	                              <FormattedMessage
979	                                defaultMessage="Pick Up in Store"
980	                                id="product_view.label.pickup_in_store"
981	                              />
982	                            </Radio>
983	                          )}
984	                        </Stack>
985	                      </RadioGroup>
986	                    </Box>
987	
988	                    {storeLocatorEnabled && (
989	                      <>
990	                        {storeName && inventoryId && (
991	                          <Text color="black" fontWeight={600} mb={2} data-testid="store-stock-status-msg">
992	                            {!isSelectedStoreOutOfStock
993	                              ? intl.formatMessage(
994	                                  {
995	                                    id: 'product_view.status.in_stock_at_store',
996	                                    defaultMessage: 'In stock at {storeName}',
997	                                  },
998	                                  {
999	                                    storeName: (
1000	                                      <Link
1001	                                        as="button"
1002	                                        color="blue.600"
1003	                                        textDecoration="underline"
1004	                                        onClick={onOpenStoreLocator}
1005	                                      >
1006	                                        {storeName}
1007	                                      </Link>
1008	                                    ),
1009	                                  },
1010	                                )
1011	                              : intl.formatMessage(
1012	                                  {
1013	                                    id: 'product_view.status.out_of_stock_at_store',
1014	                                    defaultMessage: 'Out of Stock at {storeName}',
1015	                                  },
1016	                                  {
1017	                                    storeName: (
1018	                                      <Link
1019	                                        as="button"
1020	                                        color="blue.600"
1021	                                        textDecoration="underline"
1022	                                        onClick={onOpenStoreLocator}
1023	                                      >
1024	                                        {storeName}
1025	                                      </Link>
1026	                                    ),
1027	                                  },
1028	                                )}
1029	                          </Text>
1030	                        )}
1031	
1032	                        {/* Show label if pickup is disabled due to no store/inventoryId */}
1033	                        {!pickupEnabled && !storeName && !inventoryId && (
1034	                          <Text color="black" fontWeight={600} mb={3} data-testid="pickup-select-store-msg">
1035	                            <FormattedMessage
1036	                              defaultMessage="Pick up in "
1037	                              id="product_view.label.pickup_in_select_store_prefix"
1038	                            />{' '}
1039	                            <Link as="button" color="blue.600" textDecoration="underline" onClick={onOpenStoreLocator}>
1040	                              <FormattedMessage
1041	                                defaultMessage="Select Store"
1042	                                id="product_view.label.select_store_link"
1043	                              />
1044	                            </Link>
1045	                          </Text>
1046	                        )}
1047	                      </>
1048	                    )}
1049	                  </>
1050	                )}
1051	                <Box display={isProductPartOfSet ? 'block' : ['none', 'none', 'none', 'block']}>
1052	                  {renderActionButtons()}
1053	                </Box>
1054	              </Box>
1055	            </Box>
1056	          </VStack>
1057	        </Flex>
1058	
1059	        {/* Sticky call-to-action buttons for mobile and certain product types */}
1060	        <Box
1061	          position="fixed"
1062	          bg="white"
1063	          width="100%"
1064	          display={isProductPartOfSet || isProductPartOfBundle ? 'none' : ['block', 'block', 'block', 'none']}
1065	          p={[4, 4, 6]}
1066	          left={0}
1067	          bottom={0}
1068	          zIndex={2}
1069	          boxShadow={theme.shadows.top}
1070	        >
1071	          {renderActionButtons()}
1072	        </Box>
1073	
1074	        {/* Loading overlay during express payment confirmation */}
1075	        {confirmingBasket && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}
1076	      </Flex>
1077	    );
1078	  },
1079	);
1080	
1081	ProductView.displayName = 'ProductView';
1082	
1083	/*
1084	 * The base file's `ProductViewHeader.propTypes` / `ProductView.propTypes` blocks are not
1085	 * carried over: the `ProductViewHeaderProps` / `ProductViewProps` types above express the
1086	 * same prop contract, and do so at compile time for every caller rather than as a dev-only
1087	 * runtime warning. Keeping both would duplicate the contract in two places that can drift.
1088	 */
1089	
1090	export default ProductView;
