/*
 * Copy-first port of
 * node_modules/@salesforce/retail-react-app/app/components/product-view/index.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
 *
 * Apart from the two added props described in the next paragraph, the differences from the base
 * file are the TypeScript annotations below, house formatting, and a small number of
 * optional-chaining guards that strictNullChecks requires — each flagged in place with a
 * `Deviation from the base file` comment.
 *
 * Per the SFCC bridge pattern in .claude/rules/overrideStyling.md, the default export stays a
 * faithful port with the same `forwardRef` behaviour. It carries two additive optional props
 * over the base file's surface, both documented on `ProductViewProps` below: `renderHeader` and
 * `renderVariationAttribute`. Both are behaviour-preserving when omitted — `renderHeader`
 * defaults to rendering the same private `ProductViewHeader` the base file renders inline, and
 * `renderVariationAttribute` falls through to `renderDefaultVariationAttribute`, the extracted
 * base per-attribute rendering. Neither name has any occurrences in the base package, so none of
 * the four base modules that import ProductView — product-view-modal (index and bundle),
 * bonus-product-view-modal, and pages/product-detail — passes either prop or is affected by
 * either one. (The runtime `propTypes` blocks are replaced by the TypeScript prop types; see the
 * note at the foot of the file.)
 */

import React, { forwardRef, useEffect, useMemo, useRef, useState, useCallback } from 'react';
import { useLocation } from 'react-router-dom';
import { useIntl, FormattedMessage } from 'react-intl';

import {
  Flex,
  Heading,
  Button,
  Skeleton,
  Box,
  Text,
  VStack,
  Fade,
  Stack,
  Radio,
  RadioGroup,
  useTheme,
} from '@salesforce/retail-react-app/app/components/shared/ui';

// Constants
const DELIVERY_OPTIONS = {
  DELIVERY: 'delivery',
  PICKUP: 'pickup',
};
import { useCurrency, useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
import { useAddToCartModalContext } from '@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal';
import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
import { useShopperBasketsV2Mutation as useShopperBasketsMutation } from '@salesforce/commerce-sdk-react';
import { useSFPayments, useExpressCheckoutEnabled } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';

// project components
import ImageGallery from '@salesforce/retail-react-app/app/components/image-gallery';
import Breadcrumb from '@salesforce/retail-react-app/app/components/breadcrumb';
import Link from '@salesforce/retail-react-app/app/components/link';
import withRegistration from '@salesforce/retail-react-app/app/components/with-registration';
import { Skeleton as ImageGallerySkeleton } from '@salesforce/retail-react-app/app/components/image-gallery';
import { HideOnDesktop, HideOnMobile } from '@salesforce/retail-react-app/app/components/responsive';
import QuantityPicker from '@salesforce/retail-react-app/app/components/quantity-picker';
import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
import { API_ERROR_MESSAGE } from '@salesforce/retail-react-app/app/constants';
import DisplayPrice from '@salesforce/retail-react-app/app/components/display-price';
import Swatch from '@salesforce/retail-react-app/app/components/swatch-group/swatch';
import SwatchGroup from '@salesforce/retail-react-app/app/components/swatch-group';
import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
import PromoCallout from '@salesforce/retail-react-app/app/components/product-tile/promo-callout';
import SFPaymentsExpressButtons from '@salesforce/retail-react-app/app/components/sf-payments-express-buttons';
import { EXPRESS_BUY_NOW } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';
import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
import { useCleanupTemporaryBaskets } from '@salesforce/retail-react-app/app/hooks/use-cleanup-temporary-baskets';

/*
 * These are a deliberate temporary gap, NOT evidence that no type exists — do not read them
 * that way. `@salesforce/retail-react-app` ships no TypeScript types (see
 * overrides/app/types/vendor.d.ts), but the shapes underneath are `commerce-sdk-isomorphic`'s
 * and it does export them: `ShopperProductsTypes.Product` / `.Variant` / `.Category`, and
 * `.Image` for `image` below. AGENTS.md's Type Definitions rule says to import those directly.
 *
 * Substituting them is a follow-up rather than part of this PR only because it also removes
 * three `no-explicit-any` warnings, moving a lint count this branch holds as an invariant
 * across every commit.
 */
type SfccProduct = any;
type SfccVariant = any;
type SfccCategory = any;
type SfccPriceData = any;

/** One selectable value of a variation attribute, as the base hooks shape it. */
type SfccVariationValue = { href?: string; name: string; image?: SfccProduct; value?: string; orderable?: boolean };

/** A variation attribute (colour, size, ...) with its selectable values. */
type SfccVariationAttribute = {
  id: string;
  name?: string;
  selectedValue?: SfccVariationValue;
  values: SfccVariationValue[];
};

/** The per-child orderability record ProductView writes back to its parent. */
export type ChildProductOrderability = {
  showInventoryMessage?: boolean;
  unfulfillable?: boolean;
  isOutOfStock?: boolean;
  stockLevel?: number;
  productName?: string;
};

export type ProductViewHeaderProps = {
  name?: string;
  currency?: string;
  priceData?: SfccPriceData;
  category?: SfccCategory[];
  product?: SfccProduct;
  isProductPartOfBundle?: boolean;
};

/*
 * Mirrors the base file's `ProductView.propTypes` one-for-one, with the defaults declared in
 * the destructuring below reflected as optional. `validateOrderability`'s signature is taken
 * from the default implementation the base file supplies.
 */
type ProductViewProps = {
  product?: SfccProduct;
  category?: SfccCategory[];
  showFullLink?: boolean;
  imageSize?: 'sm' | 'md';
  isWishlistLoading?: boolean;
  addToCart?: ((productSelectionValues: SfccProduct[]) => unknown) | null;
  updateCart?: ((variant: SfccVariant, quantity: number) => unknown) | null;
  addToWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
  updateWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
  isProductLoading?: boolean;
  isProductPartOfSet?: boolean;
  isProductPartOfBundle?: boolean;
  childOfBundleQuantity?: number;
  childProductOrderability?: Record<string, ChildProductOrderability>;
  setChildProductOrderability?: React.Dispatch<React.SetStateAction<Record<string, ChildProductOrderability>>>;
  isBasketLoading?: boolean;
  onVariantSelected?: (product: SfccProduct, variant: SfccVariant, quantity: number) => void;
  validateOrderability?: (
    variant: SfccVariant,
    product: SfccProduct,
    quantity: number,
    stockLevel: number,
  ) => boolean | undefined;
  showImageGallery?: boolean;
  setSelectedBundleQuantity?: (quantity: number) => void;
  selectedBundleParentQuantity?: number;
  pickupInStore?: boolean;
  setPickupInStore?: (checked: boolean) => void;
  onOpenStoreLocator?: () => void;
  showDeliveryOptions?: boolean;
  customButtons?: React.ReactElement[];
  promotionId?: string;
  maxOrderQuantity?: number | null;
  imageGalleryFooter?: React.ReactNode;
  alignItems?: string;
  controlledVariationValues?: Record<string, string> | null;
  onVariationChange?: ((attributeId: string, value: string) => void) | null;
  /**
   * The one Zimmermann addition to this component's prop surface. Replaces the header block
   * (breadcrumb, title, price, promo callout) with caller-supplied content, receiving exactly
   * the values the private `ProductViewHeader` is given so a caller can reuse or ignore any of
   * them. Defaults to rendering that same private header, so every existing caller — cart,
   * wishlist, bonus-product — is byte-identical unless it opts in.
   *
   * ProductView renders the header twice (mobile and desktop breakpoints), so this is called
   * twice with the same arguments. Keep it pure.
   */
  renderHeader?: (props: ProductViewHeaderProps) => React.ReactNode;
  /**
   * A caller-supplied override for rendering a single variation attribute (e.g. colour,
   * size), receiving the full attribute object so a caller can reuse or ignore any of its
   * fields. Falls through to `renderDefaultVariationAttribute` — the extracted base rendering
   * for that attribute — via `??` at the call site. ProductView calls this once per entry in
   * `variationAttributes`; keep it pure.
   *
   * That `??` only treats `undefined` as absent: returning `undefined` falls through to the
   * base rendering for that attribute, but returning `null` ALSO falls through and is NOT a
   * way to render nothing for that attribute — render an empty fragment instead if that's
   * genuinely the intent.
   */
  renderVariationAttribute?: (attr: SfccVariationAttribute) => React.ReactNode;
};

/*
 * The base file rebinds a function ref's `this` so the parent can reach `validateOrderability`
 * (see the `typeof ref === 'function'` branch below, and the set/bundle child refs in
 * pages/product-detail).
 */
type ProductViewRef = React.ForwardedRef<HTMLDivElement>;

/**
 * The scope ProductView rebinds onto a callback `ref`, so a parent rendering set/bundle
 * children can reach this instance's validation. See the `typeof ref === 'function'` branch
 * below. A consumer names it as the `this` parameter of its ref callback —
 * `function (this: ProductViewRefScope, ref) { ... }` — which TypeScript accepts as a `ref`
 * as written; no assertion is required at the prop site.
 */
export type ProductViewRefScope = {
  validateOrderability: (opts: { scrollErrorIntoView: boolean }) => void;
};

const ProductViewHeader = ({
  name,
  currency,
  priceData,
  category,
  product,
  isProductPartOfBundle,
}: ProductViewHeaderProps) => {
  return (
    <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
      {category && (
        <Skeleton isLoaded={category} minWidth={64}>
          <Breadcrumb categories={category} />
        </Skeleton>
      )}

      {/* Title */}
      <Skeleton isLoaded={name}>
        <Heading fontSize="2xl">{`${name}`}</Heading>
      </Skeleton>

      {!isProductPartOfBundle && (
        <>
          <Skeleton isLoaded={priceData?.currentPrice}>
            {priceData?.currentPrice && <DisplayPrice priceData={priceData} currency={currency} />}
          </Skeleton>

          <Skeleton isLoaded={product}>{product?.productPromotions && <PromoCallout product={product} />}</Skeleton>
        </>
      )}
    </VStack>
  );
};

const ButtonWithRegistration = withRegistration(Button);

/**
 * Render a product detail view that includes name, image gallery, price,
 * variant selections, action buttons
 */

const ProductView = forwardRef(
  (
    {
      product,
      category,
      showFullLink = false,
      imageSize = 'md',
      isWishlistLoading = false,
      addToCart,
      updateCart,
      addToWishlist,
      updateWishlist,
      isProductLoading,
      isProductPartOfSet = false,
      isProductPartOfBundle = false,
      childOfBundleQuantity = 0,
      childProductOrderability,
      setChildProductOrderability,
      isBasketLoading = false,
      onVariantSelected = () => {},
      validateOrderability = (variant, product, quantity, stockLevel) => {
        if (isProductLoading) return false;

        // If product has variations, a variant must be selected
        if (product?.variationAttributes?.length > 0 && !variant) {
          return false;
        }

        // Check if product (either variant or standard) is orderable and if quantity is valid
        return (variant?.orderable || product?.inventory?.orderable) && quantity > 0 && quantity <= stockLevel;
      },
      showImageGallery = true,
      setSelectedBundleQuantity = () => {},
      selectedBundleParentQuantity = 1,
      pickupInStore = false,
      setPickupInStore = () => {},
      onOpenStoreLocator = () => {},
      showDeliveryOptions = true,
      customButtons = [],
      maxOrderQuantity = null,
      imageGalleryFooter = null,
      controlledVariationValues = null,
      onVariationChange = null,
      renderHeader = (headerProps: ProductViewHeaderProps) => <ProductViewHeader {...headerProps} />,
      renderVariationAttribute,
    }: ProductViewProps,
    ref: ProductViewRef,
  ) => {
    const { currency: activeCurrency } = useCurrency();
    const showToast = useToast();
    const intl = useIntl();
    const location = useLocation();
    const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
    const {
      isOpen: isAddToCartModalOpen,
      onOpen: onAddToCartModalOpen,
      onClose: onAddToCartModalClose,
    } = useAddToCartModalContext();

    const { mutateAsync: createBasket } = useShopperBasketsMutation('createBasket');
    const { mutateAsync: addItemToBasket } = useShopperBasketsMutation('addItemToBasket');

    const theme = useTheme();
    const { confirmingBasket } = useSFPayments();
    const [showOptionsMessage, toggleShowOptionsMessage] = useState(false);
    const {
      showLoading,
      showInventoryMessage,
      inventoryMessage,
      quantity,
      minOrderQuantity,
      setQuantity,
      variant,
      variationParams,
      variationAttributes,
      stockLevel,
      stepQuantity,
      isOutOfStock,
      unfulfillable,
      isSelectedStoreOutOfStock,
      selectedStore,
    } = useDerivedProduct(
      product,
      isProductPartOfSet,
      isProductPartOfBundle,
      pickupInStore,
      controlledVariationValues,
      onVariationChange,
    );
    const priceData = useMemo(() => {
      return getPriceData(product, { quantity });
    }, [product, quantity]);
    const canAddToWishlist = !isProductLoading;
    const isProductASet = product?.type?.set;
    const isProductABundle = product?.type?.bundle;
    const errorContainerRef = useRef<HTMLDivElement | null>(null);
    const [pickupEnabled, setPickupEnabled] = useState(false);
    const storeName = selectedStore?.name;
    const inventoryId = selectedStore?.inventoryId;
    const { pdp: showExpressOnPDP } = useExpressCheckoutEnabled();

    const { disableButton, customInventoryMessage } = useMemo(() => {
      let shouldDisableButton = showInventoryMessage;
      let currentInventoryMsg = '';
      if (!shouldDisableButton && (isProductASet || isProductABundle) && childProductOrderability) {
        // if any of the children are not orderable, it will disable the add to cart button
        const unavailableChildProductKey = Object.keys(childProductOrderability).find((key) => {
          return childProductOrderability[key].showInventoryMessage;
        });
        shouldDisableButton = !!unavailableChildProductKey;
        if (unavailableChildProductKey) {
          const unavailableChildProduct = childProductOrderability[unavailableChildProductKey];
          if (unavailableChildProduct.unfulfillable) {
            currentInventoryMsg = intl.formatMessage(
              {
                defaultMessage: 'Only {stockLevel} left for {productName}!',
                id: 'use_product.message.inventory_remaining_for_product',
              },
              {
                stockLevel: unavailableChildProduct.stockLevel,
                productName: unavailableChildProduct.productName,
              },
            );
          }
          if (unavailableChildProduct.isOutOfStock) {
            currentInventoryMsg = intl.formatMessage(
              {
                defaultMessage: 'Out of stock for {productName}',
                id: 'use_product.message.out_of_stock_for_product',
              },
              { productName: unavailableChildProduct.productName },
            );
          }
        }
      }
      return { disableButton: shouldDisableButton, customInventoryMessage: currentInventoryMsg };
    }, [showInventoryMessage, childProductOrderability]);

    const validateAndShowError = (opts: { scrollErrorIntoView?: boolean } = {}) => {
      const { scrollErrorIntoView = true } = opts;
      // Validate that all attributes are selected before proceeding.
      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
      const showError = !isProductASet && !isProductABundle && !hasValidSelection;
      const scrollToError = showError && scrollErrorIntoView;

      toggleShowOptionsMessage(showError);

      if (scrollToError) {
        // Deviation from the base file: `?.`. The base dereferences `current` unguarded here
        // while guarding it in `prepareBasket` below; the two only differ if the error
        // container has not mounted, where the base throws.
        errorContainerRef.current?.scrollIntoView({
          behavior: 'smooth',
          block: 'center',
        });
      }

      return hasValidSelection;
    };
    const cleanupTemporaryBaskets = useCleanupTemporaryBaskets();

    // prepareBasket is used to prepare the basket for express payments
    // useCallback recreates prepareBasket primarily when product or quantity change, along with variant, stockLevel, and product type flags (isProductASet, isProductABundle)
    const prepareBasket = useCallback(async () => {
      // Validate that all attributes are selected before proceeding
      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
      let errorMessage = '';

      if (!hasValidSelection && !isProductASet && !isProductABundle) {
        toggleShowOptionsMessage(true);
        if (errorContainerRef.current) {
          errorContainerRef.current.scrollIntoView({
            behavior: 'smooth',
            block: 'center',
          });
        }
        errorMessage = intl.formatMessage({
          defaultMessage: 'Please select all product options before proceeding with Express Payments',
          id: 'product_view.prepareBasket',
        });

        const error: Error & { isValidationError?: boolean } = new Error(errorMessage);
        error.isValidationError = true;
        throw error;
      }

      // Clean up temporary baskets before creating a new one
      await cleanupTemporaryBaskets();

      // Create a new temporary basket
      const newBasket = await createBasket({
        parameters: {
          temporary: true,
        },
        body: {},
      });

      const selectedProduct = variant || product;
      // Use variant's productId if variant is selected, otherwise use product's id
      const productIdToUse = selectedProduct?.productId || selectedProduct?.id;

      if (!productIdToUse) {
        errorMessage = intl.formatMessage({
          defaultMessage: 'Unable to determine product ID for basket',
          id: 'product_view.prepareBasket',
        });
        throw new Error(errorMessage);
      }
      // Add the product to the temporary basket
      const basketWithItem = await addItemToBasket({
        // SDK param widening — `newBasket` is the basket just created above.
        parameters: { basketId: newBasket.basketId as string },
        body: [
          {
            productId: productIdToUse,
            quantity: quantity,
          },
        ],
      });

      return basketWithItem;
    }, [variant, product, quantity, stockLevel, isProductASet, isProductABundle]);

    const renderActionButtons = () => {
      const buttons = [];
      const buttonText = {
        update: intl.formatMessage({
          defaultMessage: 'Update',
          id: 'product_view.button.update',
        }),
        addToCart: intl.formatMessage({
          defaultMessage: 'Add to Cart',
          id: 'product_view.button.add_to_cart',
        }),
        addSetToCart: intl.formatMessage({
          defaultMessage: 'Add Set to Cart',
          id: 'product_view.button.add_set_to_cart',
        }),
        addBundleToCart: intl.formatMessage({
          defaultMessage: 'Add Bundle to Cart',
          id: 'product_view.button.add_bundle_to_cart',
        }),
        addToWishlist: intl.formatMessage({
          defaultMessage: 'Add to Wishlist',
          id: 'product_view.button.add_to_wishlist',
        }),
        addSetToWishlist: intl.formatMessage({
          defaultMessage: 'Add Set to Wishlist',
          id: 'product_view.button.add_set_to_wishlist',
        }),
        addBundleToWishlist: intl.formatMessage({
          defaultMessage: 'Add Bundle to Wishlist',
          id: 'product_view.button.add_bundle_to_wishlist',
        }),
      };

      const showError = () => {
        showToast({
          title: intl.formatMessage(API_ERROR_MESSAGE),
          status: 'error',
        });
      };

      const handleCartItem = async () => {
        const hasValidSelection = validateAndShowError();

        if (!hasValidSelection) {
          return null;
        }

        if (!addToCart && !updateCart) return null;
        if (updateCart) {
          await updateCart(variant || product, quantity);
          return;
        }
        try {
          // Guarded above: `!addToCart && !updateCart` returns early, and the `updateCart`
          // branch returns, so `addToCart` is defined here. TypeScript cannot narrow across
          // those two statements.
          const itemsAdded = await addToCart!([{ product, variant, quantity }]);
          // Open modal only when `addToCart` returns some data
          // It's possible that the item has been added to cart, but we don't want to open the modal.
          // See wishlist_primary_action for example.
          if (itemsAdded) {
            onAddToCartModalOpen({
              product,
              itemsAdded,
              selectedQuantity: quantity,
            });
          }
        } catch (e) {
          showError();
        }
      };

      const handleWishlistItem = async () => {
        if (!updateWishlist && !addToWishlist) return null;
        if (updateWishlist) {
          updateWishlist(product, variant, quantity);
          return;
        }
        // Guarded above, exactly as `addToCart` is in handleCartItem.
        addToWishlist!(product, variant, quantity);
      };

      // child product of bundles do not have add to cart button
      if ((addToCart || updateCart) && !isProductPartOfBundle) {
        buttons.push(
          <Button
            key="cart-button"
            onClick={handleCartItem}
            isDisabled={disableButton}
            isLoading={isBasketLoading}
            width="100%"
            variant="solid"
            marginBottom={4}
          >
            {updateCart
              ? buttonText.update
              : isProductASet
              ? buttonText.addSetToCart
              : isProductABundle
              ? buttonText.addBundleToCart
              : buttonText.addToCart}
          </Button>,
        );
      }

      // child product of bundles do not have add to wishlist button
      if ((addToWishlist || updateWishlist) && !isProductPartOfBundle) {
        buttons.push(
          <ButtonWithRegistration
            key="wishlist-button"
            onClick={handleWishlistItem}
            disabled={isWishlistLoading || !canAddToWishlist}
            isLoading={isWishlistLoading}
            width="100%"
            variant="outline"
            marginBottom={4}
          >
            {updateWishlist
              ? buttonText.update
              : isProductASet
              ? buttonText.addSetToWishlist
              : isProductABundle
              ? buttonText.addBundleToWishlist
              : buttonText.addToWishlist}
          </ButtonWithRegistration>,
        );
      }

      if (showExpressOnPDP && !isProductASet && !isProductPartOfBundle && activeCurrency && priceData.currentPrice) {
        buttons.push(
          <SFPaymentsExpressButtons
            key="express-buttons"
            usage={EXPRESS_BUY_NOW}
            paymentCurrency={activeCurrency}
            paymentCountryCode={null}
            initialAmount={priceData.currentPrice}
            prepareBasket={prepareBasket}
            expressButtonLayout="vertical"
            maximumButtonCount={1}
          />,
        );
      }

      // Add custom buttons if provided
      if (customButtons && customButtons.length > 0) {
        customButtons.forEach((customButton, index) => {
          buttons.push(
            React.cloneElement(customButton, {
              key: `custom-button-${index}`,
              width: customButton.props.width || '100%',
              marginBottom: customButton.props.marginBottom || 4,
            }),
          );
        });
      }

      return buttons;
    };

    // Bind the reference with our `scope` that includes the internal validate function for this component.
    // Other values can be added to this scope as required.
    if (typeof ref === 'function') {
      ref = ref.bind({ validateOrderability: validateAndShowError });
    }

    // Set the quantity of bundle child in a product bundle to ensure availability messages appear
    if (isProductPartOfBundle && quantity != selectedBundleParentQuantity * childOfBundleQuantity) {
      setQuantity(selectedBundleParentQuantity * childOfBundleQuantity);
    }

    useEffect(() => {
      if (isAddToCartModalOpen) {
        onAddToCartModalClose();
      }
    }, [location.pathname]);

    useEffect(() => {
      if (!isProductASet && !isProductABundle && validateOrderability(variant, product, quantity, stockLevel)) {
        toggleShowOptionsMessage(false);
      }
    }, [variationParams]);

    useEffect(() => {
      if (variant) {
        onVariantSelected(product, variant, quantity);
      }
    }, [variant?.productId, quantity]);

    useEffect(() => {
      if ((isProductPartOfBundle || isProductPartOfSet) && product && product.type?.item) {
        onVariantSelected(product, null, childOfBundleQuantity || quantity);
      }
    }, [product, childOfBundleQuantity, quantity, isProductPartOfBundle, isProductPartOfSet]);

    useEffect(() => {
      if (isProductPartOfBundle || isProductPartOfSet) {
        const key = product.itemId ?? product.id;
        // when showInventoryMessage is true, it means child product is not orderable
        // Deviation from the base file: optional call. The prop has no default, and the base
        // calls it unguarded — only reachable for set/bundle children, whose parent always
        // supplies it.
        setChildProductOrderability?.((previousState) => ({
          ...previousState,
          [key]: {
            showInventoryMessage,
            isOutOfStock,
            unfulfillable,
            stockLevel,
            productName: product?.name,
          },
        }));
      }
    }, [showInventoryMessage, inventoryMessage]);

    // Auto-switch off pickup in store when product becomes unavailable at selected store
    useEffect(() => {
      setPickupEnabled(!!selectedStore?.inventoryId);
      if (pickupInStore && isSelectedStoreOutOfStock) {
        setPickupInStore(false);
      }
    }, [selectedStore]);

    const handleDeliveryOptionChange = (value: string) => {
      setPickupInStore(value === DELIVERY_OPTIONS.PICKUP);
    };

    const renderDefaultVariationAttribute = (attr: SfccVariationAttribute) => {
      const { id, name, selectedValue, values } = attr;
      const swatches = values.map(({ href, name, image, value, orderable }: SfccVariationValue, index: number) => {
        // audit-allow: verbatim from base product-view (index.jsx:689); copy-first requires it unchanged
        const content = image ? (
          <Box
            height="100%"
            width="100%"
            minWidth="32px"
            backgroundRepeat="no-repeat"
            backgroundSize="cover"
            backgroundColor={name.toLowerCase()}
            backgroundImage={`url(${image.disBaseLink || image.link})`}
          />
        ) : (
          name
        );
        const hasSelection = Boolean(selectedValue?.value);
        const isSelected = selectedValue?.value === value;
        const isFirst = index === 0;
        // To mimic the behavior of a native radio input, only
        // one swatch should receive tab focus; the rest can be
        // selected using arrow keys when the swatch group has
        // focus. The focused element is the selected option or
        // the first in the group, if no option is selected.
        // This is a slight difference, for simplicity, from the
        // native element, where the first element is focused on
        // `Tab` and the _last_ element is focused on `Shift+Tab`
        const isFocusable = isSelected || (!hasSelection && isFirst);
        return (
          <Swatch
            key={value}
            href={href}
            disabled={!orderable}
            value={value}
            name={name}
            variant={id === 'color' ? 'circle' : 'square'}
            selected={isSelected}
            isFocusable={isFocusable}
          >
            {content}
          </Swatch>
        );
      });
      return (
        <SwatchGroup
          key={id}
          value={selectedValue?.value}
          displayName={selectedValue?.name || ''}
          label={intl.formatMessage(
            {
              defaultMessage: '{variantType}',
              id: 'product_view.label.variant_type',
            },
            { variantType: name },
          )}
          handleChange={onVariationChange ? (value: string) => onVariationChange(id, value) : undefined}
        >
          {swatches}
        </SwatchGroup>
      );
    };

    return (
      <Flex direction={'column'} data-testid="product-view" ref={ref}>
        {/* Basic information etc. title, price, breadcrumb*/}
        <Box display={['block', 'block', 'block', 'none']}>
          {renderHeader({
            name: product?.name,
            product,
            priceData,
            currency: product?.currency || activeCurrency,
            category,
            isProductPartOfBundle,
          })}
        </Box>
        <Flex direction={['column', 'column', 'column', 'row']}>
          {showImageGallery && (
            <Box flex={1} mr={[0, 0, 0, 6, 6]}>
              {product ? (
                <>
                  <ImageGallery
                    size={imageSize}
                    imageGroups={product.imageGroups}
                    selectedVariationAttributes={variationParams}
                    lazy={isProductPartOfSet || isProductPartOfBundle}
                  />
                  <HideOnMobile>
                    {showFullLink && product && (
                      <Link to={`/product/${product.master.masterId}`} color="blue.600">
                        <FormattedMessage id="product_view.link.full_details" defaultMessage="See full details" />
                      </Link>
                    )}
                  </HideOnMobile>
                </>
              ) : (
                <ImageGallerySkeleton />
              )}
              {/* Custom footer content (e.g., Back to Selection button) */}
              {imageGalleryFooter && (
                <Box mt={6} mb={2}>
                  {imageGalleryFooter}
                </Box>
              )}
            </Box>
          )}

          {/* Variations & Quantity Selector & CTA buttons */}
          {/* audit-allow: verbatim from base product-view (index.jsx:636-638); copy-first requires it unchanged */}
          <VStack
            align="stretch"
            spacing={8}
            flex={1}
            pb={[
              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
              4,
            ]}
          >
            <Box display={['none', 'none', 'none', 'block']}>
              {renderHeader({
                name: product?.name,
                product,
                priceData,
                currency: product?.currency || activeCurrency,
                category,
                isProductPartOfBundle,
              })}
            </Box>
            <VStack align="stretch" spacing={4}>
              {isProductPartOfBundle && (
                <Box>
                  <Text fontWeight="medium" fontSize="md" aria-label="price">
                    <label>
                      {intl.formatMessage({
                        defaultMessage: 'Quantity',
                        id: 'product_view.label.quantity',
                      })}
                      : {childOfBundleQuantity}
                    </label>
                  </Text>
                </Box>
              )}
              {/*
                                Customize the skeletons shown for attributes to suit your needs. At the point
                                that we show the skeleton we do not know how many variations are selectable. So choose
                                a a skeleton that will meet most of your needs.
                            */}
              {showLoading ? (
                <>
                  {/* First Attribute Skeleton */}
                  <Skeleton height={6} width={32} />
                  <Skeleton height={20} width={64} />

                  {/* Second Attribute Skeleton */}
                  <Skeleton height={6} width={32} />
                  <Skeleton height={20} width={64} />
                </>
              ) : (
                variationAttributes.map((attr: SfccVariationAttribute) => (
                  <React.Fragment key={attr.id}>
                    {renderVariationAttribute?.(attr) ?? renderDefaultVariationAttribute(attr)}
                  </React.Fragment>
                ))
              )}

              {/* audit-allow: verbatim from base product-view (index.jsx:754); copy-first requires it unchanged */}
              {!isProductASet && !isProductPartOfBundle && (
                <VStack align="stretch" maxWidth={'200px'}>
                  <Box fontWeight="bold">
                    <label htmlFor="quantity">
                      {intl.formatMessage({
                        defaultMessage: 'Quantity:',
                        id: 'product_view.label.quantity',
                      })}
                    </label>
                  </Box>

                  <QuantityPicker
                    id="quantity"
                    step={stepQuantity}
                    value={quantity}
                    min={minOrderQuantity}
                    {...(maxOrderQuantity != null && { max: maxOrderQuantity })}
                    onChange={(stringValue: string, numberValue: number) => {
                      // Set the Quantity of product to value of input if value number
                      if (numberValue >= 0) {
                        setQuantity(numberValue);
                        if (isProductABundle) setSelectedBundleQuantity(numberValue);
                      } else if (stringValue === '') {
                        // We want to allow the use to clear the input to start a new input so here we set the quantity to '' so NAN is not displayed
                        // User will not be able to add '' qauntity to the cart due to the add to cart button enablement rules
                        setQuantity(stringValue);
                      }
                    }}
                    onBlur={(e: React.FocusEvent<HTMLInputElement>) => {
                      // Default to 1the `minOrderQuantity` if a user leaves the box with an invalid value
                      const value = e.target.value;
                      if (parseInt(value) < 0 || value === '') {
                        setQuantity(minOrderQuantity);
                        if (isProductABundle) setSelectedBundleQuantity(minOrderQuantity);
                      }
                    }}
                    onFocus={(e: React.FocusEvent<HTMLInputElement>) => {
                      // This is useful for mobile devices, this allows the user to pop open the keyboard and set the
                      // new quantity with one click. NOTE: This is something that can be refactored into the parent
                      // component, potentially as a prop called `selectInputOnFocus`.
                      e.target.select();
                    }}
                    productName={product?.name}
                  />
                </VStack>
              )}
              <Box ref={errorContainerRef}>
                {!showLoading && showOptionsMessage && (
                  <Fade in={true}>
                    <Text color="orange.600" fontWeight={600} marginBottom={8}>
                      {intl.formatMessage({
                        defaultMessage: 'Please select all your options above',
                      })}
                    </Text>
                  </Fade>
                )}
              </Box>
              <HideOnDesktop>
                {showFullLink && product && (
                  <Link to={`/product/${product.master.masterId}`} color="blue.600">
                    <FormattedMessage id="product_view.link.full_details" defaultMessage="See full details" />
                  </Link>
                )}
              </HideOnDesktop>
              {isProductASet && <p>{product?.shortDescription}</p>}
            </VStack>

            <Box>
              {!showLoading && showInventoryMessage && !customInventoryMessage && (
                <Fade in={true}>
                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
                    {inventoryMessage}
                  </Text>
                </Fade>
              )}
              {!showLoading && customInventoryMessage && (
                <Fade in={true}>
                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
                    {customInventoryMessage}
                  </Text>
                </Fade>
              )}
              <Box>
                {showDeliveryOptions && (
                  <>
                    <Box mb={4}>
                      <Text fontWeight={600} mb={3}>
                        <FormattedMessage defaultMessage="Delivery:" id="product_view.label.delivery" />
                      </Text>
                      <RadioGroup
                        value={pickupInStore ? DELIVERY_OPTIONS.PICKUP : DELIVERY_OPTIONS.DELIVERY}
                        onChange={handleDeliveryOptionChange}
                        mb={1}
                      >
                        <Stack direction="column" spacing={2}>
                          <Radio value={DELIVERY_OPTIONS.DELIVERY} isDisabled={disableButton}>
                            <FormattedMessage
                              defaultMessage="Ship to Address"
                              id="product_view.label.ship_to_address"
                            />
                          </Radio>
                          {storeLocatorEnabled && (
                            <Radio
                              value={DELIVERY_OPTIONS.PICKUP}
                              isDisabled={!pickupEnabled || (storeName && inventoryId && isSelectedStoreOutOfStock)}
                            >
                              <FormattedMessage
                                defaultMessage="Pick Up in Store"
                                id="product_view.label.pickup_in_store"
                              />
                            </Radio>
                          )}
                        </Stack>
                      </RadioGroup>
                    </Box>

                    {storeLocatorEnabled && (
                      <>
                        {storeName && inventoryId && (
                          <Text color="black" fontWeight={600} mb={2} data-testid="store-stock-status-msg">
                            {!isSelectedStoreOutOfStock
                              ? intl.formatMessage(
                                  {
                                    id: 'product_view.status.in_stock_at_store',
                                    defaultMessage: 'In stock at {storeName}',
                                  },
                                  {
                                    storeName: (
                                      <Link
                                        as="button"
                                        color="blue.600"
                                        textDecoration="underline"
                                        onClick={onOpenStoreLocator}
                                      >
                                        {storeName}
                                      </Link>
                                    ),
                                  },
                                )
                              : intl.formatMessage(
                                  {
                                    id: 'product_view.status.out_of_stock_at_store',
                                    defaultMessage: 'Out of Stock at {storeName}',
                                  },
                                  {
                                    storeName: (
                                      <Link
                                        as="button"
                                        color="blue.600"
                                        textDecoration="underline"
                                        onClick={onOpenStoreLocator}
                                      >
                                        {storeName}
                                      </Link>
                                    ),
                                  },
                                )}
                          </Text>
                        )}

                        {/* Show label if pickup is disabled due to no store/inventoryId */}
                        {!pickupEnabled && !storeName && !inventoryId && (
                          <Text color="black" fontWeight={600} mb={3} data-testid="pickup-select-store-msg">
                            <FormattedMessage
                              defaultMessage="Pick up in "
                              id="product_view.label.pickup_in_select_store_prefix"
                            />{' '}
                            <Link as="button" color="blue.600" textDecoration="underline" onClick={onOpenStoreLocator}>
                              <FormattedMessage
                                defaultMessage="Select Store"
                                id="product_view.label.select_store_link"
                              />
                            </Link>
                          </Text>
                        )}
                      </>
                    )}
                  </>
                )}
                <Box display={isProductPartOfSet ? 'block' : ['none', 'none', 'none', 'block']}>
                  {renderActionButtons()}
                </Box>
              </Box>
            </Box>
          </VStack>
        </Flex>

        {/* Sticky call-to-action buttons for mobile and certain product types */}
        <Box
          position="fixed"
          bg="white"
          width="100%"
          display={isProductPartOfSet || isProductPartOfBundle ? 'none' : ['block', 'block', 'block', 'none']}
          p={[4, 4, 6]}
          left={0}
          bottom={0}
          zIndex={2}
          boxShadow={theme.shadows.top}
        >
          {renderActionButtons()}
        </Box>

        {/* Loading overlay during express payment confirmation */}
        {confirmingBasket && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}
      </Flex>
    );
  },
);

ProductView.displayName = 'ProductView';

/*
 * The base file's `ProductViewHeader.propTypes` / `ProductView.propTypes` blocks are not
 * carried over: the `ProductViewHeaderProps` / `ProductViewProps` types above express the
 * same prop contract, and do so at compile time for every caller rather than as a dev-only
 * runtime warning. Keeping both would duplicate the contract in two places that can drift.
 */

export default ProductView;

