/**
 * Scoped to this molecule's own contract per testing.md: the AC-1/AC-5 branch logic and the
 * roving-tabindex invariant that this component alone is responsible for proving. Keyboard-focus
 * movement and pagination-window interaction are exercised in index.stories.tsx's `play`
 * functions instead — both are "user-facing interaction in a single component," which
 * testing.md routes to Storybook `play`, not Vitest.
 *
 * ZimmColourSwatch is left real (not mocked): composition is part of the contract under test —
 * this suite proves how many colours the molecule chooses to render and which one it marks
 * selected, not how a swatch itself looks (that is ZimmColourSwatch's own suite's job).
 *
 * Every render is wrapped three ways:
 *   - `ChakraProvider theme={theme}` — the real theme, not Chakra's default. Without it,
 *     `useMultiStyleConfig` for both this recipe and the atom's own resolve against a theme with
 *     no such keys registered — same reasoning as zimmProductMeta/index.test.tsx's own note.
 *   - `MemoryRouter` — ZimmColourSwatch can render a react-router `Link`, which throws outside one.
 *   - `IntlProvider` — this component calls `useIntl()` directly, which throws outside one
 *     (react-intl's `invariantIntlContext`).
 *
 * ZimmIcon is mocked at the smallest surface — the known, documented Vitest gap (it pulls in the
 * base SFCC icons barrel, which has a top-level side effect that fails under Vitest's SVG
 * transform; see testing.md). Mocked via the same relative specifier index.tsx itself imports,
 * so there is no cross-specifier module-resolution question to reason about.
 */
import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ChakraProvider } from '@chakra-ui/react';
import { MemoryRouter } from 'react-router-dom';
import { IntlProvider } from 'react-intl';
import theme from 'app/theme';
import { ZimmColourSwatchGroup } from './index';
import type { ZimmColourSwatchValue } from './index';

vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));

const IMAGE = (seed: string) => `https://picsum.photos/seed/zimm-colour-${seed}/400/600`;

const BAY_BLUE: ZimmColourSwatchValue = {
  value: 'BAYBL',
  name: 'Bay Blue',
  href: '/p.html?color=BAYBL',
  imageUrl: IMAGE('bay-blue'),
};
const IVORY: ZimmColourSwatchValue = {
  value: 'IVORY',
  name: 'Ivory',
  href: '/p.html?color=IVORY',
  imageUrl: IMAGE('ivory'),
};
const BLACK: ZimmColourSwatchValue = {
  value: 'BLACK',
  name: 'Black',
  href: '/p.html?color=BLACK',
  imageUrl: IMAGE('black'),
};
/** No `imageUrl` — exercises AC 5's filter. */
const ROSE_UNPOPULATED: ZimmColourSwatchValue = { value: 'ROSE', name: 'Rose Pink', href: '/p.html?color=ROSE' };
const GOLD_UNPOPULATED: ZimmColourSwatchValue = { value: 'GOLD', name: 'Gold', href: '/p.html?color=GOLD' };

const renderGroup = (props: Partial<React.ComponentProps<typeof ZimmColourSwatchGroup>> = {}) =>
  render(
    <ChakraProvider theme={theme}>
      <IntlProvider locale="en-AU" defaultLocale="en-AU">
        <MemoryRouter>
          <ZimmColourSwatchGroup label="Colour" values={[BAY_BLUE, IVORY, BLACK]} {...props} />
        </MemoryRouter>
      </IntlProvider>
    </ChakraProvider>,
  );

describe('ZimmColourSwatchGroup', () => {
  test('renders the label only, with no radios, when exactly one colour is populated (AC 1)', () => {
    renderGroup({ selectedName: 'Bay Blue', selectedValue: 'BAYBL', values: [BAY_BLUE] });

